import{N,opticalPSF,mtfCurves,sceneKernel,fft2,linear,srgb}from './optics.js';
let cacheKey='',cache=[];
export function convolve(input,w,h,kernel,size,key){const W=1024,H=512,mid=(size-1)/2,kr=new Float64Array(W*H),ki=new Float64Array(W*H);for(let y=0;y<size;y++)for(let x=0;x<size;x++)kr[((y-mid+H)%H)*W+(x-mid+W)%W]=kernel[y*size+x];fft2(kr,ki,W,H);
// Edge extension avoids adding artificial dark borders. The 64-pixel padding fits inside the FFT array.
if(cacheKey!==key){cache=[];for(let c=0;c<3;c++){const r=new Float64Array(W*H),i=new Float64Array(W*H);for(let y=-mid;y<h+mid;y++)for(let x=-mid;x<w+mid;x++){const sy=Math.max(0,Math.min(h-1,y)),sx=Math.max(0,Math.min(w-1,x));r[((y+H)%H)*W+(x+W)%W]=linear(input[(sy*w+sx)*4+c]);}fft2(r,i,W,H);cache.push({r,i});}cacheKey=key;}
const out=new Uint8ClampedArray(w*h*4);for(let c=0;c<3;c++){const r=new Float64Array(W*H),i=new Float64Array(W*H),a=cache[c];for(let j=0;j<r.length;j++){r[j]=a.r[j]*kr[j]-a.i[j]*ki[j];i[j]=a.r[j]*ki[j]+a.i[j]*kr[j];}fft2(r,i,W,H,true);for(let y=0;y<h;y++)for(let x=0;x<w;x++)out[(y*w+x)*4+c]=srgb(r[y*W+x]);}for(let j=3;j<out.length;j+=4)out[j]=255;return out;}
if(typeof self!=='undefined')self.onmessage=({data:d})=>{try{const{psf,angle}=opticalPSF(d.state);const k=sceneKernel(psf,angle,(8/640)*Math.PI/180);const output=convolve(d.input,d.width,d.height,k.kernel,k.size,d.sceneKey||d.state.scene);const plot=new Float32Array(256*256);for(let y=0;y<256;y++)for(let x=0;x<256;x++){// Central 256 pixels shown without renormalizing the cropped field.
plot[y*256+x]=psf[(y+N/2-128)*N+x+N/2-128];}const curves=mtfCurves(psf,angle,d.state.pupil);postMessage({id:d.id,output,psf:plot,field:256*angle*180/Math.PI,retained:k.retained,...curves},[output.buffer,plot.buffer]);}catch(error){postMessage({id:d.id,error:String(error)});}};
